/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAs = require( './as/get.js' );
var setAs = require( './as/set.js' );

var getStart = require( './start/get.js' );
var setStart = require( './start/set.js' );

var getStep = require( './step/get.js' );
var setStep = require( './step/set.js' );

var getStop = require( './stop/get.js' );
var setStop = require( './stop/set.js' );

var getProperties = require( './properties/get.js' );


// VARIABLES //

var debug = logger( 'vega:sequence-transform:main' );


// MAIN //

/**
* Sequence transform constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {number} options.start - starting value of the sequence
* @param {number} options.stop - ending value (exclusive) of the sequence
* @param {number} [options.step=1] - step value between sequence entries
* @param {string} [options.as='data'] - output field name for the sequence values
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {SequenceTransform} sequence transform instance
*
* @example
* var transform = new SequenceTransform({
*     'start': 0,
*     'stop': 5,
*     'step': 1
* });
* // returns <SequenceTransform>
*/
function SequenceTransform( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof SequenceTransform ) ) {
		return new SequenceTransform( options );
	}
	EventEmitter.call( this );

	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}

	// Check for required properties...
	if ( !hasProp( options, 'start' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify a starting value.' );
	}
	if ( !hasProp( options, 'stop' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify an ending value.' );
	}

	// Resolve the default configuration:
	opts = defaults( options.start, options.stop );

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}

	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( SequenceTransform, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof SequenceTransform
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( SequenceTransform, 'name', 'SequenceTransform' );

/**
* Output field name for the sequence values.
*
* @name as
* @memberof SequenceTransform.prototype
* @type {string}
* @default 'data'
*
* @example
* var transform = new SequenceTransform({
*     'start': 0,
*     'stop': 5,
*     'as': 'x'
* });
*
* var v = transform.as;
* // returns 'x'
*/
setReadWriteAccessor( SequenceTransform.prototype, 'as', getAs, setAs );

/**
* Starting value of the sequence.
*
* @name start
* @memberof SequenceTransform.prototype
* @type {number}
*
* @example
* var transform = new SequenceTransform({
*     'start': 0,
*     'stop': 5
* });
*
* var v = transform.start;
* // returns 0
*/
setReadWriteAccessor( SequenceTransform.prototype, 'start', getStart, setStart );

/**
* Ending value (exclusive) of the sequence.
*
* @name stop
* @memberof SequenceTransform.prototype
* @type {number}
*
* @example
* var transform = new SequenceTransform({
*     'start': 0,
*     'stop': 5
* });
*
* var v = transform.stop;
* // returns 5
*/
setReadWriteAccessor( SequenceTransform.prototype, 'stop', getStop, setStop );

/**
* Step value between sequence entries.
*
* @name step
* @memberof SequenceTransform.prototype
* @type {number}
* @default 1
*
* @example
* var transform = new SequenceTransform({
*     'start': 0,
*     'stop': 10,
*     'step': 2
* });
*
* var v = transform.step;
* // returns 2
*/
setReadWriteAccessor( SequenceTransform.prototype, 'step', getStep, setStep );

/**
* Sequence transform properties.
*
* @name properties
* @memberof SequenceTransform.prototype
* @type {Array<string>}
*
* @example
* var transform = new SequenceTransform({
*     'start': 0,
*     'stop': 5
* });
*
* var v = transform.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( SequenceTransform.prototype, 'properties', getProperties );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof SequenceTransform.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var transform = new SequenceTransform({
*     'start': 0,
*     'stop': 5,
*     'step': 1
* });
*
* var v = transform.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( SequenceTransform.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = SequenceTransform;
